using System.Text.Json;
using AeroScience.Missions;
using AeroScience.Shared;
using Microsoft.Data.Sqlite;
using Xunit;
namespace AeroScience.Tests;

public sealed class ObservationResearchTests:IDisposable
{
    readonly string root=Path.Combine(Path.GetTempPath(),"aeroscience-pilot-research-"+Guid.NewGuid());readonly MissionStore missions;readonly ScienceStore science;
    public ObservationResearchTests(){var p=new StorageManager(new PreferenceStore(root)).Initialize();missions=new(Path.Combine(p.MissionDirectory,"missions.db"));missions.Initialize();science=new(p.ScienceLibraryDirectory);science.Initialize();missions.ScienceLibrary=science;}
    PersonalResearchCard Card(ObservationResearchDefinition? definition=null)=>missions.SaveResearchCard(new("Pilot investigation",null,ObservationFlight:definition??new()));
    static TelemetryFrame Frame(DateTimeOffset at)=>new(at,TelemetrySource.Simulated,"Synthetic P08 / not MSFS",40,-75,1000,null,100,100,100,0,0,0,0,0);
    (Guid Id,DateTimeOffset Start,DateTimeOffset End) Flight(PersonalResearchCard card,int count,bool position=true,string category="observation",TelemetrySource source=TelemetrySource.Simulated){
        var start=DateTimeOffset.UtcNow.AddSeconds(-20);var end=start.AddSeconds(15);var id=missions.Create("Synthetic pilot research",Frame(start) with{Source=source},start,plan:missions.CreateResearchPlan(card.Id,card.Revision));
        for(var i=0;i<=15;i++)missions.Append(id,Frame(start.AddSeconds(i)) with{Source=source});
        for(var i=0;i<count;i++)missions.AddMarker(id,new(category,"Original pilot account "+i,Guid.NewGuid()),start.AddSeconds(i+1),position?Frame(start.AddSeconds(i+1)):null,"Live context is not a retained measurement");
        missions.Finish(id,MissionStatus.Completed,end,"Synthetic end");return(id,start,end);
    }
    PersonalResearchAttempt Evaluate((Guid Id,DateTimeOffset Start,DateTimeOffset End) f,PersonalResearchCard c)=>missions.EvaluateResearchAttempt(new(Guid.NewGuid(),f.Id,f.Start,f.End,CardId:c.Id),science:science);
    [Theory][InlineData(0,ResearchAttemptOutcome.InsufficientEvidence)][InlineData(1,ResearchAttemptOutcome.PartialCollection)][InlineData(3,ResearchAttemptOutcome.CollectionComplete)]
    public void DocumentationOutcomesUseOriginalNotesNotFlightPathOrScientificTruth(int count,ResearchAttemptOutcome expected){var c=Card();var f=Flight(c,count);var result=Evaluate(f,c);Assert.Equal(expected,result.Outcome);Assert.Equal(count,result.ObservationFlight!.Documented);Assert.Equal(5,result.Version);Assert.Null(result.Card.FlightRegime);Assert.Null(result.Survey);Assert.Null(result.AtmosphericProfile);var review=missions.ReviewObservationEvidence(result,science);Assert.True(review.MatchesSavedEvidence);Assert.Equal(count,review.Preview.Length);Assert.All(review.Preview,p=>Assert.Equal("Pilot Observation",p.Kind));Assert.Contains("hypothesis",result.ObservationFlight.Limitations[0]);}
    [Theory][InlineData(false,ResearchAttemptOutcome.CollectionComplete)][InlineData(true,ResearchAttemptOutcome.PartialCollection)]
    public void MissingPositionRemainsUnavailableAndCannotMeetAnExplicitLocationRequirement(bool required,ResearchAttemptOutcome expected){var c=Card(new(RequirePosition:required));var f=Flight(c,3,false);var r=Evaluate(f,c);Assert.Equal(expected,r.Outcome);Assert.Equal(0,r.ObservationFlight!.Located);Assert.All(missions.ReviewObservationEvidence(r,science).Preview,p=>{Assert.Null(p.Latitude);Assert.Null(p.AltitudeMslFeet);Assert.Null(p.PositionTimestampUtc);});}
    [Fact]public void CategoriesFrozenRevisionsAndEmptyMarkersRemainDistinct(){var c=Card(new(Categories:["observation","finding"],RequireEveryCategory:true));var f=Flight(c,3);var r=Evaluate(f,c);Assert.Equal(ResearchAttemptOutcome.PartialCollection,r.Outcome);Assert.Equal(0,Assert.Single(r.ObservationFlight!.Categories,q=>q.Category=="finding").Documented);
        var changed=missions.SaveResearchCard(new("Revised question",null,c.Id,1,ObservationFlight:c.ObservationFlight! with{MinimumObservations=1}));Assert.Equal(2,changed.Revision);Assert.Equal(3,missions.ResearchCard(c.Id,1).ObservationFlight!.MinimumObservations);Assert.Equal(1,Evaluate(f,c).Card.Revision);
        var blank=Flight(c,0);missions.AddMarker(blank.Id,new("finding","  "),blank.Start.AddSeconds(1),Frame(blank.Start.AddSeconds(1)),null);Assert.Equal(ResearchAttemptOutcome.InsufficientEvidence,Evaluate(blank,c).Outcome);
    }
    [Fact]public void PreparationReusesDefaultsAndCustomizeMakesIndependentEditableDefinitionWithoutStartingScience(){var request=new ResearchStarterRequest(1,Guid.NewGuid(),ObservationResearch.Template,ResearchEntryIntent.FlyNow);var p=missions.PrepareResearchStarter(request);Assert.Equal(5,p.Card.Version);Assert.Equal(MissionTemplateKind.ObservationFlight,p.Plan.Template);Assert.True(p.Plan.StartScienceArmed);Assert.DoesNotContain(p.Plan.Instruments!,i=>i.Enabled);Assert.Empty(p.Plan.Waypoints??[]);Assert.True(missions.PrepareResearchStarter(request).Reused);
        var repeat=missions.PrepareResearchStarter(request with{RequestId=Guid.NewGuid()});Assert.Equal(p.Card.Id,repeat.Card.Id);var copy=missions.PrepareResearchStarter(new(1,Guid.NewGuid(),ObservationResearch.Template,ResearchEntryIntent.Customize,new(p.Card.Id,1)));Assert.NotEqual(p.Card.Id,copy.Card.Id);Assert.True(MissionStore.CompatibleResearchCards(p.Card,copy.Card));
    }
    [Theory][InlineData("paused")][InlineData("stale")][InlineData("future")][InlineData("invalid")][InlineData("disconnected")]
    public void CoordinatorNeverInventsMarkerCoordinatesAndKeepsOneContinuousFlight(string input){var c=Card();using var research=new ResearchOperations(missions,science);var coordinator=new MissionCoordinator(missions,1000,research:research);var at=DateTimeOffset.UtcNow;var frame=Frame(at);coordinator.Apply(new(new(ConnectionState.Connected,TelemetrySource.Simulated,"Synthetic",at),frame));var flight=coordinator.Start(new("P08 actual coordinator",PlanId:missions.CreateResearchPlan(c.Id,1).Id));
        frame=input switch{"paused"=>frame with{IsPaused=true},"stale"=>frame with{TimestampUtc=at.AddMinutes(-1)},"future"=>frame with{TimestampUtc=at.AddMinutes(1)},"invalid"=>frame with{Latitude=95},_=>frame};coordinator.Apply(new(new(input=="disconnected"?ConnectionState.Disconnected:ConnectionState.Connected,TelemetrySource.Simulated,"Synthetic",at),frame));
        var marker=coordinator.AddMarker(flight.Id,new("observation","Pilot description",Guid.NewGuid()));Assert.Null(marker.Latitude);Assert.Null(marker.AltitudeMslFeet);Assert.Equal(ObservationQuality.Unavailable,marker.PilotObservation!.PositionQuality);Assert.Equal(flight.Id,coordinator.Snapshot().ActiveMission!.Id);Assert.Equal(CollectionPhase.Armed,Assert.IsType<CollectionState>(coordinator.ScienceCollection(flight.Id).State).Phase);coordinator.End(flight.Id);
    }
    [Fact]public void NativeAndBrowserRetriesShareDurableMarkerIdentityWithoutRetargetingOrCopyingNotes(){var c=Card();var coordinator=new MissionCoordinator(missions,1000);var at=DateTimeOffset.UtcNow;coordinator.Apply(new(new(ConnectionState.Connected,TelemetrySource.Simulated,"Synthetic",at),Frame(at)));var flight=coordinator.Start(new("Native pilot",PlanId:missions.CreateResearchPlan(c.Id,1).Id));var id=Guid.NewGuid();var command=JsonSerializer.Serialize(new ToolbarCommand(1,id,"marker",MissionId:flight.Id,Category:"finding",Notes:"Original observation"),WireJson.Options);
        var first=new ToolbarCommandHandler(coordinator);var reply=first.Handle(command);Assert.Equal(reply,first.Handle(command));var marker=Assert.Single(missions.StreamMarkers(flight.Id));Assert.Equal(id,marker.Id);
        var restarted=new ToolbarCommandHandler(coordinator);using var again=JsonDocument.Parse(restarted.Handle(command));Assert.True(again.RootElement.GetProperty("ok").GetBoolean());Assert.Equal(PreflightReadiness.Hash(marker),PreflightReadiness.Hash(coordinator.AddMarker(flight.Id,new("finding","Original observation",id))));Assert.Throws<InvalidOperationException>(()=>coordinator.AddMarker(flight.Id,new("finding","Changed",id)));Assert.Single(missions.StreamMarkers(flight.Id));coordinator.End(flight.Id);Assert.Equal(PreflightReadiness.Hash(marker),PreflightReadiness.Hash(coordinator.AddMarker(flight.Id,new("finding","Original observation",id))));
    }
    [Fact]public void OptionalSupportingScienceUsesOnlyRecordedOriginalUnitsAndCanBeUnavailableWithoutLosingPilotDocumentation(){var c=Card(new(SupportingInstruments:["ambient-temperature"]));var f=Flight(c,3);var dataset=science.EnsureDataset(missions.Detail(f.Id)!.Mission,new("ambient-temperature",true),missions.Research(f.Id));
        ScienceObservation O(int n,double value,string unit="degC",ScienceProvenance provenance=ScienceProvenance.SimulatorReported,ObservationQuality quality=ObservationQuality.Valid)=>new(0,dataset.Id,f.Id,"ambient-temperature",f.Start.AddSeconds(n),"temperature",value,unit,provenance,"Original synthetic source",40,-75,1000,quality,f.Start.AddSeconds(n));
        science.Append([O(1,17),O(2,99,"unsupported"),O(3,22,provenance:ScienceProvenance.Derived),O(4,20,quality:ObservationQuality.Paused)]);var r=Evaluate(f,c);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,r.Outcome);Assert.Equal(1,Assert.Single(r.ObservationFlight!.SupportingMeasurements).ValidReadings);Assert.Equal(3,Assert.Single(r.ObservationFlight.SupportingMeasurements).ExcludedReadings);var review=missions.ReviewObservationEvidence(r,science);Assert.True(review.SupportingEvidenceMatches);Assert.Equal(17,Assert.Single(review.SupportingPreview).Value);Assert.All(review.Preview.Where(p=>p.SupportingObservationIds.Length>0),p=>Assert.Equal([review.SupportingPreview[0].Id],p.SupportingObservationIds));
        var unavailable=missions.ReviewObservationEvidence(r,null);Assert.True(unavailable.MatchesSavedEvidence);Assert.False(unavailable.SupportingEvidenceMatches);Assert.Empty(unavailable.SupportingPreview);Assert.Equal(3,unavailable.Preview.Length);
    }
    [Fact]public void RetainedNotesComparisonRestartAndDeletionPurgeDependentResearchButPreserveUnrelatedFlightContext(){var c=Card();var a=Flight(c,3);var b=Flight(c,1);var first=Evaluate(a,c);var second=Evaluate(b,c);var reopened=new MissionStore(missions.DatabasePath);reopened.Initialize();Assert.True(reopened.ReviewObservationEvidence(first,science).MatchesSavedEvidence);
        var comparison=reopened.CompareResearch(c.Id,new([new(first.Id,ResearchAttemptKind.PostflightInterval,first.Id),new(second.Id,ResearchAttemptKind.PostflightInterval,second.Id)]),science:science);Assert.All(comparison.Entries,e=>Assert.True(e.ObservationFlight!.MatchesSavedEvidence));
        var plain=missions.Create("Unrelated flight context",Frame(a.Start),a.Start);missions.AddMarker(plain,new("observation","Keep unrelated context"),a.Start,Frame(a.Start),null);missions.Finish(plain,MissionStatus.Completed,a.End,"end");
        var coordinator=new MissionCoordinator(missions,1000);var preview=science.PreviewCollectedDeletion(new([a.Id]),missions);Assert.Empty(preview.Blockers);Assert.Equal(3,preview.PilotObservations);Assert.Equal("Completed",science.DeleteCollectedScience(new(preview.Id,preview.SelectionHash),missions,coordinator.EnterMaintenance).State);Assert.Empty(missions.StreamMarkers(a.Id));Assert.Empty(missions.ResearchAttempts(flightId:a.Id));Assert.NotEmpty(missions.StreamSamples(a.Id));Assert.Single(missions.StreamMarkers(plain));Assert.True(missions.ReviewObservationEvidence(second,science).MatchesSavedEvidence);Assert.Throws<InvalidOperationException>(()=>Evaluate(a,c));
    }
    [Fact]public void ChangedOriginalTextInvalidatesReviewInsteadOfRewritingHistory(){var c=Card();var f=Flight(c,3);var r=Evaluate(f,c);using(var db=new SqliteConnection("Data Source="+missions.DatabasePath)){db.Open();using var cmd=db.CreateCommand();cmd.CommandText="UPDATE research_markers SET payload_json=json_set(payload_json,'$.notes','tampered') WHERE mission_id=$id";cmd.Parameters.AddWithValue("$id",f.Id.ToString());cmd.ExecuteNonQuery();}var review=missions.ReviewObservationEvidence(r,science);Assert.False(review.MatchesSavedEvidence);Assert.Empty(review.Preview);Assert.Equal(r.Evidence.Sha256,missions.ResearchAttempt(r.Id).Evidence.Sha256);}
    [Fact]public void UnsupportedDefinitionsAndCancelledWorkAreRejected(){foreach(var r in new[]{new ObservationResearchDefinition(Version:2),new(Categories:[]),new(SupportingInstruments:["thermal-imager"]),new(MinimumObservations:0),new(Question:"")})Assert.Throws<ArgumentException>(()=>ObservationResearch.Validate(r));var c=Card();var f=Flight(c,3);using var token=new CancellationTokenSource();token.Cancel();Assert.Throws<OperationCanceledException>(()=>missions.EvaluateResearchAttempt(new(Guid.NewGuid(),f.Id,f.Start,f.End,CardId:c.Id),token.Token,science));}
    [Fact]public void InFlightResearchNotesHaveOriginalUtcAndUnknownLocationAndArePurgedFromRegisteredBackups(){var c=Card(new(MinimumObservations:1,Categories:["note"]));var at=DateTimeOffset.UtcNow.AddSeconds(-1);var id=missions.Create("Pilot note archive",Frame(at),at,plan:missions.CreateResearchPlan(c.Id,1));var request=new NoteRequest("Exact original account","in-flight",Guid.NewGuid());var note=missions.AddNote(id,request);Assert.Equal(PreflightReadiness.Hash(note),PreflightReadiness.Hash(missions.AddNote(id,request)));Assert.Throws<InvalidOperationException>(()=>missions.AddNote(id,request with{Text="Changed"}));missions.Append(id,Frame(note.TimestampUtc));var end=DateTimeOffset.UtcNow.AddSeconds(1);missions.Finish(id,MissionStatus.Completed,end,"end");var result=missions.EvaluateResearchAttempt(new(Guid.NewGuid(),id,at,end,CardId:c.Id),science:science);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,result.Outcome);var entry=Assert.Single(missions.ReviewObservationEvidence(result,science).Preview);Assert.Equal(note.Text,entry.Text);Assert.Equal(note.TimestampUtc,entry.TimestampUtc);Assert.Null(entry.Latitude);Assert.Equal("note",entry.Category);
        var folder=Path.Combine(root,"registered-backups");Directory.CreateDirectory(folder);var backup=DataBackup.Create(missions.DatabasePath,folder,false);Assert.True(File.Exists(backup));var coordinator=new MissionCoordinator(missions,1000);var preview=science.PreviewCollectedDeletion(new([id]),missions);Assert.Equal("Completed",science.DeleteCollectedScience(new(preview.Id,preview.SelectionHash),missions,coordinator.EnterMaintenance).State);Assert.Empty(missions.StreamNotes(id));using var db=new SqliteConnection("Data Source="+backup);db.Open();using var cmd=db.CreateCommand();cmd.CommandText="SELECT COUNT(*) FROM research_notes WHERE mission_id=$id";cmd.Parameters.AddWithValue("$id",id.ToString());Assert.Equal(0L,cmd.ExecuteScalar());Assert.Throws<InvalidOperationException>(()=>missions.AddNote(id,new("Must not silently regenerate")));
    }
    [Fact]public void InterruptedAttemptAndSciencePausesCannotInventSupportingMeasurements(){var c=Card(new(SupportingInstruments:["ambient-temperature"]));var f=Flight(c,3);using(var db=new SqliteConnection("Data Source="+missions.DatabasePath)){db.Open();using var cmd=db.CreateCommand();cmd.CommandText="UPDATE missions SET status='Interrupted' WHERE id=$id";cmd.Parameters.AddWithValue("$id",f.Id.ToString());cmd.ExecuteNonQuery();}var r=Evaluate(f,c);Assert.Equal(ResearchAttemptOutcome.PartialCollection,r.Outcome);Assert.Equal(0,Assert.Single(r.ObservationFlight!.SupportingMeasurements).ValidReadings);Assert.Empty(missions.ReviewObservationEvidence(r,science).SupportingPreview);}
    [Fact]public void BoundedPreviewDoesNotLimitRetainedDocumentationOrDetermineCompleteness(){var c=Card(new(MinimumObservations:101));var start=DateTimeOffset.UtcNow.AddMinutes(-3);var end=start.AddSeconds(120);var id=missions.Create("Longer documentation archive",Frame(start),start,plan:missions.CreateResearchPlan(c.Id,1));for(var i=0;i<101;i++){var at=start.AddSeconds(i+1);missions.Append(id,Frame(at));missions.AddMarker(id,new("observation","Original account "+i),at,Frame(at),null);}missions.Finish(id,MissionStatus.Completed,end,"end");var r=missions.EvaluateResearchAttempt(new(Guid.NewGuid(),id,start,end,CardId:c.Id),science:science);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,r.Outcome);Assert.Equal(101,r.ObservationFlight!.Documented);var review=missions.ReviewObservationEvidence(r,science);Assert.True(review.MatchesSavedEvidence);Assert.True(review.Downsampled);Assert.InRange(review.Preview.Length,1,100);Assert.Equal(101,missions.StreamMarkers(id).Count());}
    [Fact]public void FullUnicodeObservationDefinitionFitsNativePacketWithoutTruncatingFrozenCriteria(){var text=new string('漢',500);var c=Card(new(Question:text,IntendedObservations:text,Approach:text,Categories:ScienceCatalog.MarkerCategories,SupportingInstruments:["ambient-temperature","ambient-pressure","ambient-wind","ambient-density"]));var coordinator=new MissionCoordinator(missions,1000);var flight=coordinator.Start(new("Bounded native definition",PlanId:missions.CreateResearchPlan(c.Id,1).Id));var reply=new ToolbarCommandHandler(coordinator).Handle(JsonSerializer.Serialize(new ToolbarCommand(1,Guid.NewGuid(),"research-state",MissionId:flight.Id),WireJson.Options));Assert.True(System.Text.Encoding.UTF8.GetByteCount(reply)<8000);using var json=JsonDocument.Parse(reply);Assert.True(json.RootElement.GetProperty("ok").GetBoolean(),reply);Assert.Equal(text,json.RootElement.GetProperty("research").GetProperty("cards")[0].GetProperty("card").GetProperty("observationFlight").GetProperty("approach").GetString());coordinator.End(flight.Id);}
    [Fact]public void OptionalQuantitativeComparisonsRejectMixedDemoAndSimulatorProvenance(){
        foreach(var withSupport in new[]{false,true}){var c=Card(new(SupportingInstruments:withSupport?["ambient-temperature"]:[]));var a=Evaluate(Flight(c,3),c);var b=Evaluate(Flight(c,3,source:TelemetrySource.Simulator),c);var selection=new ResearchComparisonRequest([new(a.Id,ResearchAttemptKind.PostflightInterval,a.Id),new(b.Id,ResearchAttemptKind.PostflightInterval,b.Id)]);
            if(withSupport)Assert.Throws<ArgumentException>(()=>missions.CompareResearch(c.Id,selection,science:science));else Assert.True(missions.CompareResearch(c.Id,selection,science:science).DifferentSources);
        }
    }
    public void Dispose(){science.Dispose();SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}
}
